import { useRef, useState } from 'react'
import {
  getShopPlatformList,
  addShopPlatform,
  editShopPlatform,
  deleteShopPlatform,
  updateShopPlatformStatus,
  SystemConfigTypes
} from '@/apis/admin/system-config'
import { uploadImage } from '@/apis/admin/site'
import ExcelTable from '@/components/exportExcel'
import { ActionType, ProColumns, ModalForm, ProFormText, ProFormDigit, ProFormSelect } from '@ant-design/pro-components'
import {
  Button,
  Popconfirm,
  message,
  Tag,
  Space,
  Upload,
  Image,
  Tooltip
} from 'antd'
import {
  PlusOutlined,
  EditOutlined,
  DeleteOutlined,
  CheckCircleOutlined,
  StopOutlined,
  ShoppingCartOutlined,
  UploadOutlined,
  ShopOutlined
} from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'
import type { UploadFile, UploadProps } from 'antd/es/upload/interface'

// 状态映射
const statusMap: Record<number, { text: string; color: string }> = {
  1: { text: '启用', color: 'success' },
  2: { text: '禁用', color: 'default' },
}

const EcommercePlatform: React.FC = () => {
  const actionRef = useRef<ActionType>()
  const [modalVisible, setModalVisible] = useState(false)
  const [modalTitle, setModalTitle] = useState('新增电商平台')
  const [editingRecord, setEditingRecord] = useState<SystemConfigTypes.ShopPlatformListDto | null>(null)
  const [formSubmitting, setFormSubmitting] = useState(false)
  const [logoUrl, setLogoUrl] = useState<string>('')
  const [fileList, setFileList] = useState<UploadFile[]>([])

  // 打开新增弹窗
  const handleAdd = () => {
    setEditingRecord(null)
    setLogoUrl('')
    setFileList([])
    setModalTitle('新增电商平台')
    setModalVisible(true)
  }

  // 打开编辑弹窗
  const handleEdit = (record: SystemConfigTypes.ShopPlatformListDto) => {
    setEditingRecord(record)
    setLogoUrl(record.logoUrl || '')
    setFileList(record.logoUrl ? [{
      uid: '-1',
      name: 'logo.png',
      status: 'done',
      url: record.logoUrl
    }] : [])
    setModalTitle('编辑电商平台')
    setModalVisible(true)
  }

  // 保存电商平台
  const handleSave = async (values: any) => {
    if (!logoUrl) {
      message.error('请上传平台Logo')
      return
    }

    setFormSubmitting(true)
    try {
      if (editingRecord) {
        // 编辑
        const res = await editShopPlatform(editingRecord.id, {
          id: editingRecord.id,
          name: values.name,
          logoUrl: logoUrl,
          sort: values.sort,
          status: values.status
        })
        if (res.code === ResultEnum.SUCCESS) {
          message.success('保存成功')
          setModalVisible(false)
          actionRef.current?.reload()
        } else {
          message.error('保存失败')
        }
      } else {
        // 新增
        const res = await addShopPlatform({
          logoUrl: logoUrl,
          name: values.name,
          sort: values.sort,
          status: values.status
        })
        if (res.code === ResultEnum.SUCCESS) {
          message.success('新增成功')
          setModalVisible(false)
          actionRef.current?.reload()
        } else {
          message.error('新增失败')
        }
      }
    } catch (e) {
      console.error('保存电商平台失败:', e)
      message.error('操作失败')
    } finally {
      setFormSubmitting(false)
    }
  }

  // 更新状态
  const handleUpdateStatus = async (record: SystemConfigTypes.ShopPlatformListDto, newStatus: number) => {
    try {
      const res = await updateShopPlatformStatus(record.id, { id: record.id })
      if (res.code === ResultEnum.SUCCESS) {
        message.success(newStatus === 1 ? '启用成功' : '禁用成功')
        actionRef.current?.reload()
      } else {
        message.error('操作失败')
      }
    } catch (e) {
      console.error('更新状态失败:', e)
      message.error('操作失败')
    }
  }

  // 删除电商平台
  const handleDelete = async (record: SystemConfigTypes.ShopPlatformListDto) => {
    try {
      const res = await deleteShopPlatform(record.id, { id: record.id })
      if (res.code === ResultEnum.SUCCESS) {
        message.success('删除成功')
        actionRef.current?.reload()
      } else {
        message.error('删除失败')
      }
    } catch (e) {
      console.error('删除电商平台失败:', e)
      message.error('操作失败')
    }
  }

  // 上传配置
  const uploadProps: UploadProps = {
    name: 'file',
    listType: 'picture-card',
    fileList,
    maxCount: 1,
    beforeUpload: (file) => {
      const isImage = file.type.includes('image/')
      if (!isImage) {
        message.error('只支持图片格式!')
        return Upload.LIST_IGNORE
      }
      const isLt2M = file.size / 1024 / 1024 < 2
      if (!isLt2M) {
        message.error('图片大小不能超过2MB')
        return Upload.LIST_IGNORE
      }
      return true
    },
    onChange: ({ fileList: newFileList }) => {
      setFileList(newFileList)
    },
    onRemove: () => {
      setLogoUrl('')
      setFileList([])
    },
    customRequest: async ({ file, onSuccess, onError }) => {
      try {
        const formData = new FormData()
        formData.append('file', file)
        formData.append('bizType', 'avatar')
        const res = await uploadImage(formData)
        if (res.code === ResultEnum.SUCCESS && res.data?.url) {
          setLogoUrl(res.data.url)
          onSuccess?.(res.data)
          message.success('上传成功')
        } else {
          onError?.(new Error('上传失败'))
          message.error('上传失败')
        }
      } catch (e) {
        onError?.(e as Error)
        message.error('上传失败')
      }
    }
  }

  // 表格列定义
  const columns: ProColumns<SystemConfigTypes.ShopPlatformListDto>[] = [
    {
      title: '平台ID',
      dataIndex: 'id',
      key: 'id',
      width: 100,
      hideInSearch: true,
      render: (text) => (
        <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 500 }}>
          {text}
        </span>
      ),
    },
    {
      title: '平台Logo',
      dataIndex: 'logoUrl',
      key: 'logoUrl',
      width: 120,
      hideInSearch: true,
      render: (text) => (
        text ? (
          <Image
            src={text as string}
            alt="平台Logo"
            style={{
              width: 48,
              height: 48,
              borderRadius: 8,
              objectFit: 'contain',
              border: '1px solid #f0f0f0',
              padding: 4
            }}
            preview={false}
          />
        ) : (
          <div style={{
            width: 48,
            height: 48,
            borderRadius: 8,
            background: '#f5f5f5',
            border: '1px solid #d9d9d9',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center'
          }}>
            <ShopOutlined style={{ fontSize: 20, color: '#999' }} />
          </div>
        )
      ),
    },
    {
      title: '平台名称',
      dataIndex: 'name',
      key: 'name',
      width: 160,
    },
    {
      title: '排序值',
      dataIndex: 'sort',
      key: 'sort',
      width: 100,
      hideInSearch: true,
      render: (text) => (
        <span style={{ fontFamily: 'Courier New, monospace' }}>{text}</span>
      ),
    },
    {
      title: '状态',
      dataIndex: 'status',
      key: 'status',
      width: 100,
      valueType: 'select',
      valueEnum: {
        1: { text: '启用', status: 'Success' },
        2: { text: '禁用', status: 'Default' },
      },
      render: (_, record) => {
        const status = statusMap[record.status]
        return <Tag color={status?.color || 'default'}>{status?.text || '未知'}</Tag>
      },
    },
    {
      title: '操作',
      key: 'option',
      valueType: 'option',
      fixed: 'right',
      width: 140,
      render: (_, record) => [
        <Tooltip title="编辑" key={`${record.id}-edit`}>
          <Button
            type="link"
            title="编辑"
            icon={<EditOutlined />}
            onClick={() => handleEdit(record)}
          />
        </Tooltip>,
        record.status === 1 ? (
          <Tooltip title="禁用" key={`${record.id}-disable`}>
            <Popconfirm
              title="确定要禁用该电商平台吗？"
              onConfirm={() => handleUpdateStatus(record, 2)}
              okText="确定"
              cancelText="取消"
            >
              <Button type="link" danger title="禁用" icon={<StopOutlined />} />
            </Popconfirm>
          </Tooltip>
        ) : (
          <Tooltip title="启用" key={`${record.id}-enable`}>
            <Button
              type="link"
              title="启用"
              icon={<CheckCircleOutlined />}
              style={{ color: '#52c41a' }}
              onClick={() => handleUpdateStatus(record, 1)}
            />
          </Tooltip>
        ),
        <Tooltip title="删除" key={`${record.id}-delete`}>
          <Popconfirm
            title="确定要删除该电商平台吗？"
            description="删除后不可恢复"
            onConfirm={() => handleDelete(record)}
            okText="确定"
            cancelText="取消"
          >
            <Button type="link" danger title="删除" icon={<DeleteOutlined />} />
          </Popconfirm>
        </Tooltip>,
      ],
    },
  ]

  return (
    <>
      {/* 提示信息 */}
      <div style={{
        marginBottom: 16,
        padding: '12px 16px',
        background: '#e6f7ff',
        border: '1px solid #91d5ff',
        borderRadius: 8,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between'
      }}>
        <div style={{ color: '#096dd9', fontSize: 14 }}>
          用于退货时选择电商平台，禁用的平台不会在小程序端展示。
        </div>
      </div>

      <ExcelTable
        key="ecommerce-platform-list"
        columns={columns}
        requestFn={async (params) => {
          const { page, pageSize, name, status } = params
          return await getShopPlatformList({
            page,
            pageSize,
            name,
            status
          })
        }}
        actionRef={actionRef}
        rowSelection={false}
        options={{
          fullScreen: false,
          reload: true,
          setting: false,
          density: false
        }}
        toolBarRenderFn={() => [
          <Button
            key="add"
            type="primary"
            icon={<PlusOutlined />}
            onClick={handleAdd}
          >
            新增电商平台
          </Button>,
        ]}
        scroll={{ x: 800 }}
      />

      {/* 新增/编辑弹窗 */}
      <ModalForm
        title={
          <Space>
            <ShoppingCartOutlined style={{ color: '#1890ff' }} />
            {modalTitle}
          </Space>
        }
        open={modalVisible}
        onOpenChange={(visible) => {
          if (!visible) {
            setLogoUrl('')
            setFileList([])
          }
          setModalVisible(visible)
        }}
        onFinish={handleSave}
        initialValues={editingRecord ? {
          name: editingRecord.name,
          sort: editingRecord.sort,
          status: editingRecord.status
        } : {
          status: 1
        }}
        submitter={{
          submitButtonProps: {
            loading: formSubmitting,
          },
        }}
        layout="horizontal"
        labelCol={{ flex: '0 0 100px' }}
        wrapperCol={{ flex: '1 1 auto' }}
        width={480}
      >
        <div style={{ marginBottom: 16 }}>
          <div style={{ marginBottom: 8, color: '#ff4d4f' }}>* 平台Logo</div>
          <Upload {...uploadProps}>
            {fileList.length >= 1 ? null : (
              <div>
                <UploadOutlined />
                <div style={{ marginTop: 8 }}>上传Logo</div>
              </div>
            )}
          </Upload>
          <div style={{ marginTop: 8, fontSize: 12, color: '#999' }}>
            支持 jpg、png、gif 格式，≤ 2MB
          </div>
        </div>
        <ProFormText
          name="name"
          label="平台名称"
          placeholder="例如：淘宝"
          rules={[{ required: true, message: '请输入平台名称' }]}
        />
        <ProFormDigit
          name="sort"
          label="排序值"
          min={0}
          fieldProps={{ style: { width: 200 } }}
          rules={[{ required: true, message: '请输入排序值' }]}
        />
        <ProFormSelect
          name="status"
          label="状态"
          options={[
            { label: '启用', value: 1 },
            { label: '禁用', value: 2 },
          ]}
          rules={[{ required: true, message: '请选择状态' }]}
        />
      </ModalForm>
    </>
  )
}

export default EcommercePlatform